function wa(){app.innerHTML=`<div class="pg"><h1>Chat</h1>${Object.entries(C).map(([k,c])=>{const l=[...c.msgs.slice(0,c.live!=null?(c.shown??c.live):1e9)].reverse().find(m=>/^[ma]\|/.test(m));return`<div class="row" onclick="chat('${k}')">${avs(c)}<div><b>${c.name}</b><small>${esc(l?l.split('|')[1]:'')}</small></div>${c.live!=null&&(c.shown??c.live)<c.msgs.length?'<u class="ub">●</u>':''}</div>`}).join('')}</div>`}
function chat(k){const c=C[k];app.innerHTML=`<div class="pg wab"><div class="hd" style="background:#f6f6f6"><span class="back" onclick="wa()">‹</span>${avs(c,'width:38px;height:38px;font-size:18px').replace('<i ',`<i onclick="prof('${k}')" `)}<div onclick="prof('${k}')"><b>${c.name}</b><small id="sub">${c.sub}</small></div></div><div class="msgs" id="ms">${c.msgs.slice(0,c.live!=null?(c.shown??c.live):1e9).map(bub).join('')}</div><div class="bar"><input id="in" placeholder="Ketik pesan" onkeydown="event.key=='Enter'&&send('${k}')"><button onclick="send('${k}')">➤</button></div></div>`;const m=$('#ms');m.scrollTop=m.scrollHeight;if(c.live!=null&&(c.shown??c.live)<c.msgs.length)stream(k)}
function send(k){const v=$('#in').value.trim();if(!v)return;const c=C[k],i=c.live!=null&&c.shown!=null&&c.shown<c.msgs.length?c.shown:c.msgs.length;c.msgs.splice(i,0,'a|'+v);if(c.live!=null)c.shown=Math.max(c.shown??0,i+1);chat(k);$('#in').focus()}
function prof(k){const c=C[k];app.innerHTML=`<div class="pg" style="align-items:center;text-align:center;background:#f2f2f7"><div class="hd" style="align-self:stretch"><span class="back" onclick="chat('${k}')">‹</span></div>${avs(c,'width:110px;height:110px;font-size:50px')}<h1 style="margin-bottom:2px">${c.name}</h1><span style="color:#777">${c.no}</span><label class="spb" style="margin-top:12px;cursor:pointer;background:#007aff;color:#fff">Ganti foto profil<input type="file" accept="image/*" hidden onchange="setAv('${k}',this.files[0])"></label><p style="background:#fff;padding:14px;border-radius:12px;margin:20px;align-self:stretch;text-align:left"><small style="color:#888">Info</small><br>${c.about}</p></div>`}
