/* ===== SPOTIFY ===== */
let AC,tm,cur=-1,on=false,aud;
function tone(f){AC=AC||new(window.AudioContext||window.webkitAudioContext)();const o=AC.createOscillator(),g=AC.createGain(),n=AC.currentTime;o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.25,n);g.gain.exponentialRampToValueAtTime(.001,n+.4);o.connect(g);g.connect(AC.destination);o.start();o.stop(n+.4)}
function play(i){stopA();cur=i;on=true;const t=T[i];if(t.u){aud=new Audio(t.u);aud.play();aud.onended=()=>{on=false;spot()}}else{let p=0;tm=setInterval(()=>{const n=t.s[p++%t.s.length];if(n!==null)tone(261.6*2**(n/12))},t.b||280)}spot()}
function stopA(){clearInterval(tm);if(aud){aud.pause();aud=null}on=false}
function tog(){if(cur<0)return play(0);if(on){stopA();spot()}else play(cur)}
function addSong(f){if(!f)return;T.push({n:f.name.replace(/\.[^.]+$/,''),a:'Dari HP',u:URL.createObjectURL(f)});play(T.length-1)}
function spot(){app.innerHTML=`<div class="pg sp"><h1>Koleksi kamu</h1>${T.map((t,i)=>`<div class="row" onclick="play(${i})"><i class="av" style="background:${PH[i%9].split(',')[0]};border-radius:6px">${cur==i&&on?'♫':'▶'}</i><div><b style="${cur==i?'color:#1ed760':''}">${esc(t.n)}</b><small>${esc(t.a)}</small></div></div>`).join('')}<label class="spb" style="align-self:center;margin:16px;cursor:pointer">+ Tambah lagu (mp3)<input type="file" accept="audio/*" hidden onchange="addSong(this.files[0])"></label><div class="pbar" style="margin-top:auto"><div style="flex:1"><b>${cur<0?'Belum ada lagu':esc(T[cur].n)}</b><br><small style="color:#aaa">${cur<0?'Pilih lagu':esc(T[cur].a)}</small></div><button onclick="tog()">${on?'❚❚':'▶'}</button></div></div>`}
