function photos(){app.innerHTML=`<div class="pg"><h1>Foto</h1><div class="ph">${PH.map((p,i)=>`<div style="background:${p.startsWith('url')?p:`linear-gradient(135deg,${p})`}" onclick="view(${i})"></div>`).join('')}</div><label class="spb" style="align-self:center;margin:16px;cursor:pointer;background:#007aff;color:#fff">+ Tambah foto<input type="file" accept="image/*" hidden onchange="addPh(this.files[0])"></label></div>`}
function addPh(f){if(f){PH.unshift(`url(${URL.createObjectURL(f)}) center/cover`);photos()}}
function view(i){const p=PH[i],bg=p.startsWith('url')?p:`linear-gradient(135deg,${p})`;app.innerHTML=`<div class="pg" style="background:#000"><div class="hd" style="color:#fff"><span class="back" onclick="photos()">‹</span></div><div style="flex:1;background:${bg}"></div><div style="padding:14px 14px 34px;text-align:center"><button class="spb" style="background:#007aff;color:#fff" onclick="wall(${i})">Jadikan wallpaper</button></div></div>`}
