function setAv(k,f){if(f){C[k].img=URL.createObjectURL(f);prof(k)}}
function badge(){const n=Object.values(C).filter(c=>c.live!=null&&(c.shown??c.live)<c.msgs.length).length;document.querySelectorAll('.bd').forEach(b=>{b.textContent=n;b.style.display=n?'grid':'none'})}
