function stream(k){clearTimeout(stt);const c=C[k];if(c.shown==null)c.shown=c.live;sk=k;const nx=()=>{if(sk!=k||!$('#ms'))return;const m=c.msgs[c.shown];if(!m){$('#sub').textContent=c.sub;return}const[t,x]=m.split('|');$('#sub').textContent=t=='m'?'mengetik...':c.sub;stt=setTimeout(()=>{if(sk!=k||!$('#ms'))return;c.shown++;$('#ms').insertAdjacentHTML('beforeend',bub(m));$('#ms').scrollTop=1e9;if(t=='m')tone(660);nx()},t=='t'||t=='x'?500:600+Math.min(x.length,80)*40)};nx()}
const L=$('#lock');let y0=0;
