function callUI(n){const o=document.createElement('div');o.className='ov';o.style.cssText='background:#1c1c1ee8;color:#fff;z-index:66';o.innerHTML=`<i class="av" style="width:90px;height:90px;font-size:40px;background:#8e8e93">${esc(n)[0]}</i><b style="font-size:24px">${esc(n)}</b><span id="cs2">Memanggil...</span><button class="spb" style="background:#e53935;color:#fff;margin-top:40px" onclick="clearInterval(window.ctm);this.parentNode.remove()">Akhiri</button>`;$('#screen').appendChild(o);let s=0;setTimeout(()=>{const e=$('#cs2');if(!e)return;e.textContent='0:00';window.ctm=setInterval(()=>{s++;e.textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0')},1000)},2000)}
