function nocam(){const v=$('#cv');if(v)v.outerHTML='<div style="flex:1;display:grid;place-items:center;text-align:center;color:#999;padding:30px">Kamera tidak bisa diakses.<br>Izinkan kamera di browser, atau buka link ini langsung (bukan di dalam frame).</div>'}
