let swT=0,swI=null;const swf=t=>String(Math.floor(t/6000)).padStart(2,'0')+':'+String(Math.floor(t/100)%60).padStart(2,'0')+'.'+String(t%100).padStart(2,'0');
function swGo(){if(swI){clearInterval(swI);swI=null}else swI=setInterval(()=>{swT++;const e=$('#sw');e&&(e.textContent=swf(swT))},10);jam('sw')}
