/* Kalkulator & Cuaca */
let ce='';
function calc(){const K=['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','='];app.innerHTML=`<div class="pg" style="background:#000;justify-content:flex-end;padding-bottom:30px"><div id="cd" style="color:#fff;font-size:70px;font-weight:200;text-align:right;padding:0 22px;overflow:hidden;white-space:nowrap">${ce||'0'}</div><div class="kp2">${K.map(k=>`<u style="${k=='0'?'grid-column:span 2;border-radius:36px;justify-content:flex-start;padding-left:28px;':''}background:${'÷×−+='.includes(k)?'#ff9500':(k=='AC'||k=='±'||k=='%')?'#a5a5a5':'#333'};color:${(k=='AC'||k=='±'||k=='%')?'#000':'#fff'}" onclick="kc('${k}')">${k}</u>`).join('')}</div></div>`}
function kc(k){if(k=='AC')ce='';else if(k=='='){try{if(/^[0-9+\-*/.()×÷−% ]+$/.test(ce))ce=String(+Function('return ('+ce.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/%/g,'/100')+')')().toFixed(8))}catch(e){ce='Error'}}else if(k=='±')ce=ce.startsWith('-')?ce.slice(1):'-'+ce;else ce+=k;$('#cd').textContent=ce||'0'}
