const ALB=['Favorit','Langit','Kucing','Selfie','Bersama Teman'];let pAl=null,pTb='k';
const flt=a=>a=='Favorit'?PHO.filter(p=>p.fav):PHO.filter(p=>p.al==a);
const pgrid=l=>l.length?`<div class="ph">${l.map(p=>`<div style="background:${p.b}" onclick="view(${PHO.indexOf(p)})"></div>`).join('')}</div>`:`<p style="text-align:center;color:#8e8e93;padding:50px 30px">Belum ada foto. Ketuk "+ Tambah foto" untuk memasukkan fotomu.</p>`;
