function ph1(t,a){pTb=t;pAl=a;let b;if(a)b=`<div class="hd"><span class="back" onclick="ph1('a',null)">‹</span><b style="font-size:20px">${a}</b></div>${pgrid(flt(a))}${padd}`;else if(t=='a')b=`<h1>Album</h1>`+ALB.map(x=>`<div class="row" onclick="ph1('a','${x}')"><i class="av" style="border-radius:8px;background:${(flt(x)[0]||{b:'#ddd'}).b}"></i><div><b>${x}</b><small>${flt(x).length}</small></div></div>`).join('');else b=`<h1>Koleksi</h1>${pgrid(PHO)}<div style="text-align:center;color:#8e8e93;font-size:13px;padding:6px">${PHO.length} Foto</div>${padd}`;app.innerHTML=`<div class="pg">${b}</div>`+tbar(t,[['k','🖼️','Koleksi'],['a','🗂️','Album']],'ph1x')}
