function addPh(fl){[...fl].forEach(f=>PHO.unshift({b:`url(${URL.createObjectURL(f)}) center/cover`,al:pAl&&pAl!='Favorit'?pAl:null}));ph1(pTb,pAl)}
function view(i){const p=PHO[i];app.innerHTML=`<div class="pg" style="background:#000;color:#fff"><div class="hd"><span class="back" onclick="ph1(pTb,pAl)" style="color:#fff">‹</span><span style="margin-left:auto;font-size:22px" onclick="PHO[${i}].fav=!PHO[${i}].fav;view(${i})">${p.fav?'♥':'♡'}</span></div><div id="vi" style="flex:1;background:${p.b}"></div><div style="display:flex;justify-content:space-between;padding:14px 20px 34px;font-size:13px"><span onclick="view(Math.max(0,${i}-1))">‹ Sebelumnya</span><span onclick="wall(${i})">Jadikan wallpaper</span><span onclick="view(Math.min(PHO.length-1,${i}+1))">Berikutnya ›</span></div></div>`;let x0=0;const v=$('#vi');v.onpointerdown=e=>x0=e.clientX;v.onpointerup=e=>{const d=e.clientX-x0;if(d>60)view(Math.max(0,i-1));else if(d<-60)view(Math.min(PHO.length-1,i+1))}}
